const create = () => createAdminImport(actor.toHexString(), make());
const mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const provider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [{ scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Album', source: 'folder', evidence: input.manifest.rootLabel }] : [] };
const errorCode = (code: string) => (error: unknown) => error instanceof AdminImportError && error.code === code;
const deferred = () => { let resolve!: () => void; const promise = new Promise<void>(r => { resolve = r; }); return { promise, resolve }; };
