test('a project saved in a newer draft format is read-only: edits, analysis, adoption, decisions, publication and cover selection are refused unchanged', async () => {
    const { id, item } = await newerProject(), before = await stored(id), by = a1.toHexString(), revision = item.revision;
    let calls = 0; const counted: ImportAnalysisProvider = { configured: () => true, analyze: async input => { calls++; return provider.analyze(input); } };
    for (const work of [
        () => editAdminImport(by, id, { ...mutation(revision), draft: item.draft }),
        () => analyzeAdminImport(by, id, mutation(revision), counted),
        () => adoptAdminImportSuggestions(by, id, { ...mutation(revision), generation: 1, selectedIds: [item.suggestions[0].id], rejectIds: [] }),
        () => decideAdminImportDuplicates(by, id, { ...mutation(revision), decisions: item.decisions }),
        () => publishAdminImport(by, id, mutation(revision)),
        () => selectAdminImportCover(by, id, { ...mutation(revision), slotId: null })
    ]) await assert.rejects(work(), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    // Refusals precede any change: no receipt, revision, draft or analysis is written.
    assert.deepEqual(await stored(id), before);
    // A stored receipt still replays its original response.
    const edit = before!.receipts.find(receipt => receipt.kind === 'edit')!;
    const replay = await editAdminImport(by, id, { operationId: edit.operationId, expectedRevision: edit.revision - 1, draft: legacyDraftView(before!.draft, before!.manifest) });
    assert.deepEqual(replay.receipt, { operationId: edit.operationId, kind: 'edit', revision: edit.revision }); assert.deepEqual(await stored(id), before);
    // Its queued analysis is never claimed, so no provider call and no checkpoint happen.
    assert.equal(await runAdminImportWorkerOnce(counted), false); assert.equal(calls, 0); assert.deepEqual(await stored(id), before);
    // Stopping work stays admitted and keeps the newer format.
    const cancelled = await cancelAdminImportAnalysis(a2.toHexString(), id, mutation(revision));
    assert.equal(cancelled.item.analysis.state, 'cancelled'); assert.equal(cancelled.receipt!.kind, 'cancel-analysis'); assert.equal(cancelled.item.revision, revision + 1);
    const after = await stored(id); assert.equal(after!.draftVersion, 3); assert.deepEqual(after!.draft, before!.draft); assert.deepEqual(after!.draftOrigins, before!.draftOrigins);
    assert.equal(after!.receipts.at(-1)!.kind, 'cancel-analysis'); assert.equal(calls, 0);
});
