    assert.deepEqual(inputs[0].baseline.album, { title: '', artistName: 'Lorem Ensemble', releaseDate: null, visibility: 'public' });
    const doc = await stored(id), ids = [1, 2].map(index => importDigest({ importId: id, generation: 1, chunk: 0, index }).slice(0, 24)), key = named.item.draft.album.artists[0].key;
    assert.deepEqual(doc!.suggestions.map(value => [value.id, value.field, value.baseline, value.value]), [
        [ids[0], 'title', '', 'Album'], [ids[1], 'artists', named.item.draft.album.artists, [{ key, name: 'Ipsum Quartet', role: 'primary', joinPhrase: null, musicBrainzId: null }]]]);
    const done = await getAdminImport(actor.toHexString(), id); assert.equal(done.item.analysis.state, 'complete');
    const adopted = await adoptAdminImportSuggestions(actor.toHexString(), id, { ...mutation(done.item.revision), generation: 1, selectedIds: [ids[1]], rejectIds: [ids[0]] });
    assert.deepEqual(adopted.item.draft.album.artists.map(value => [value.key, value.name]), [[key, 'Ipsum Quartet']]);
